bool render_display_frame(SDL_Renderer* renderer, const VM& vm,
                          DisplayFrameTextureCache& cache, bool refresh) {
    const auto [width,height] = vm.current_mode_dimensions();
    if (!refresh && cache.matches(renderer, static_cast<int>(width), static_cast<int>(height)))
        return cache.draw(vm.screen_shake_offset_x(), vm.screen_shake_offset_y());
    const auto& frame = vm.display_frame_view();
    if (frame.width == 0 || frame.height == 0 ||
        frame.rgba.size() !=
            static_cast<std::size_t>(frame.width) * frame.height * 4U) {
        cache.invalidate();
        return false;
    }
    return cache.upload(renderer,static_cast<int>(frame.width),static_cast<int>(frame.height),frame.rgba,
        retain_cpu_pixel_copies()?std::span<const uint8_t>{}:std::span<const uint8_t>(frame.pixels)) &&
        cache.draw(vm.screen_shake_offset_x(), vm.screen_shake_offset_y());
}
